import torch
import triton
import triton.language as tl

from flag_gems.runtime import torch_device_fn
from flag_gems.utils import libentry, tl_extra_shim

logger = logging.getLogger(__name__)

NUM_SIPS = 24


@libentry()
@triton.jit(do_not_specialize=["N"])
def erf_kernel(x_ptr, o_ptr, N, BLOCK: tl.constexpr, HAS_TAIL: tl.constexpr):
    """erf via ``fast_tanhf(P(x))`` with P an odd degree-7 polynomial.

    ``P(x) = x * Q(t)``, ``t = min(x*x, 10.24)`` (the clamp keeps Q's negative
    leading term from flipping the sign of P for |x| > 3.2; there P grows
    linearly and tanh saturates, so erf -> +-1 exactly like libdevice). The odd
    form needs no abs, no sign select and no branch: +-inf and NaN come out
    compatible with the libdevice body (tanh(+-inf * K) = +-1; NaN survives the
    final x multiply), and the result is exact at x = 0. Coefficients are the
    same weighted (sech^2 * atanh(erf)) Lawson fit reused from the validated
    ``special_erfc`` fast path (erf == 1 - erfc); max abs error vs
    torch.special.erf (CPU, fp64) is 1.35e-5 over the whole real line (fp32
    suite gate atol=1e-4: 7x margin; measured on device on randn 1M plus edge
    values incl. +-inf/NaN).

    The libdevice extern ``__ef_erff`` is a software slow path: measured L600
    512M flat kernel, extern body 5.24 ms (fp32) / 5.30 ms (fp16) vs 1.34 ms
    copy floor, while this body is one hardware fast_tanhf plus 7 fp32 ALU ops
    and runs at the copy floor for fp32 (1.35 ms) and at the 16-bit ALU wall
    for fp16/bf16 (1.27 ms; native torch.special.erf is 7.7-9.2 ms).
    """
    pid = tl.program_id(0)
    num_pids = tl.num_programs(0)
    if HAS_TAIL:
        num_blocks = (N + BLOCK - 1) // BLOCK
    else:
        num_blocks = N // BLOCK
    for block_id in tl.range(pid, num_blocks, num_pids):
        off = block_id * BLOCK + tl.arange(0, BLOCK)
        if HAS_TAIL:
            mask = off < N
            x = tl.load(x_ptr + off, mask=mask, other=0.0).to(tl.float32)
        else:
            x = tl.load(x_ptr + off).to(tl.float32)
        t = tl.minimum(x * x, 10.24)
